const phoneError = document.getElementById('phoneError');

const validationState = {
    fullName: false,
    email: false,
    phone: true
};

function validateFullName() {
    const value = fullNameInput.value.trim();
    const isValid = value.length > 0;

    if (!isValid && fullNameInput.touched) {
        fullNameError.textContent = 'Full name is required';
        fullNameError.classList.add('show');
    } else {
        fullNameError.textContent = '';
        fullNameError.classList.remove('show');
    }

    validationState.fullName = isValid;
    return isValid;
}

function validateEmail() {
    const value = emailInput.value.trim();
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    const isValid = emailRegex.test(value);

    if (!isValid && emailInput.touched) {
        if (value.length === 0) {
            emailError.textContent = 'Email address is required';
        } else {
            emailError.textContent = 'Please enter a valid email address';
        }
        emailError.classList.add('show');
    } else {
        emailError.textContent = '';
        emailError.classList.remove('show');
    }

    validationState.email = isValid;
    return isValid;
}

function validatePhone() {
    const value = phoneInput.value.trim();

    if (value.length === 0) {
        phoneError.textContent = '';
        phoneError.classList.remove('show');
        validationState.phone = true;
        return true;
    }

    const phoneRegex = /^[\d\s\-\+\(\)]{10,}$/;
    const isValid = phoneRegex.test(value);

    if (!isValid && phoneInput.touched) {
        phoneError.textContent = 'Please enter a valid phone number';
        phoneError.classList.add('show');
    } else {
        phoneError.textContent = '';
        phoneError.classList.remove('show');
    }

    validationState.phone = isValid;
    return isValid;
}

fullNameInput.addEventListener('blur', () => {
    fullNameInput.touched = true;
    validateFullName();
});

fullNameInput.addEventListener('input', () => {
    if (fullNameInput.touched) {
        validateFullName();
    }
});

emailInput.addEventListener('blur', () => {
    emailInput.touched = true;
    validateEmail();
});

emailInput.addEventListener('input', () => {
    if (emailInput.touched) {
        validateEmail();
    }
});

phoneInput.addEventListener('blur', () => {
    phoneInput.touched = true;
    validatePhone();
});

phoneInput.addEventListener('input', () => {
    if (phoneInput.touched) {
        validatePhone();
    }
});

form.addEventListener('submit', (e) => {
    e.preventDefault();

    fullNameInput.touched = true;
    emailInput.touched = true;
    phoneInput.touched = true;

    const isFullNameValid = validateFullName();
    const isEmailValid = validateEmail();
    const isPhoneValid = validatePhone();

    if (isFullNameValid && isEmailValid && isPhoneValid) {
