            fullName: fullNameInput.value.trim(),
            email: emailInput.value.trim(),
            phone: phoneInput.value.trim()
        };

        console.log('Form submitted successfully:', formData);
        alert('Thank you for contacting support! We will get back to you soon.');
        form.reset();

        fullNameInput.touched = false;
        emailInput.touched = false;
        phoneInput.touched = false;

        fullNameError.textContent = '';
        fullNameError.classList.remove('show');
        emailError.textContent = '';
        emailError.classList.remove('show');
        phoneError.textContent = '';
        phoneError.classList.remove('show');
    } else {
        const firstInvalidField = !isFullNameValid ? fullNameInput : 
                                  !isEmailValid ? emailInput : 
                                  phoneInput;
        firstInvalidField.focus();
    }
});
